mapper.update:
UPDATE dms_shop_order SET status = 1,
pay_type = #{payType},
pay_time = CURRENT_TIMESTAMP, update_time = CURRENT_TIMESTAMP WHERE id = #{id} AND status = 0 AND COALESCE(tenant_id, 1) = #{tenantId}

UPDATE dms_shop_order
SET service_remark=#{serviceRemark}, update_time=CURRENT_TIMESTAMP
WHERE id=#{id} AND COALESCE(tenant_id, 1) = #{tenantId}

mapper.select:
SELECT id
FROM dms_shop_order
WHERE status = 0 AND create_time <= #{cutoffTime}
  AND COALESCE(tenant_id, 1) = #{tenantId}
ORDER BY create_time ASC, id ASC
LIMIT #{limit}

SELECT shop_order.id
FROM dms_shop_order shop_order
WHERE shop_order.status = 2
  AND shop_order.delivery_time IS NOT NULL
  AND shop_order.delivery_time <= #{cutoffTime}
  AND COALESCE(shop_order.tenant_id, 1) = #{tenantId}
  AND NOT EXISTS (
      SELECT 1 FROM dms_shop_after_sale after_sale
      WHERE after_sale.order_id = shop_order.id
        AND after_sale.status NOT IN (1, 2, 3)
  )
ORDER BY shop_order.delivery_time ASC, shop_order.id ASC
LIMIT #{limit}
